def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))

    # Find same-colored diagonal pairs. Extend their diagonal away from
    # the rest of the pattern, choosing the side whose next cell is empty.
    pairs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                    pairs.append((color, r, c, nr, nc, dr, dc))

    for color, r, c, nr, nc, dr, dc in pairs:
        # Test the two outward directions from the pair.
        candidates = [
            (nr + dr, nc + dc, dr, dc),
            (r - dr, c - dc, -dr, -dc),
        ]
        chosen = None
        for rr, cc, sr, sc in candidates:
            if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                chosen = (rr, cc, sr, sc)
                break
        if chosen is None:
            continue

        rr, cc, sr, sc = chosen
        while 0 <= rr < h and 0 <= cc < w:
            if out[rr][cc] == bg:
                out[rr][cc] = color
            rr += sr
            cc += sc

    return out
